  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `source_line_no` int DEFAULT NULL,
  `source_snapshot_json` text COLLATE utf8mb4_unicode_ci,
  `actual_quantity` decimal(20,2) DEFAULT NULL,
  `qualified_quantity` decimal(20,2) DEFAULT NULL,
  `unqualified_quantity` decimal(20,2) DEFAULT NULL,
  `quality_images` text COLLATE utf8mb4_unicode_ci,
  `quality_remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quality_required_snapshot` bit(1) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_sku_id` (`sku_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3309033 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WMS 入库单明细';
