--
-- Table structure for table `wms_shipment_order`
--

DROP TABLE IF EXISTS `wms_shipment_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wms_shipment_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出库单号',
  `type` int NOT NULL COMMENT '出库类型',
  `order_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '单据日期',
  `status` int NOT NULL DEFAULT '0' COMMENT '出库状态',
  `biz_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务订单号',
  `merchant_id` bigint DEFAULT NULL COMMENT '客户编号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `warehouse_id` bigint NOT NULL COMMENT '仓库编号',
  `area_id` bigint NOT NULL DEFAULT '0' COMMENT '库区编号',
  `total_quantity` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '总数量',
  `total_price` decimal(16,2) DEFAULT NULL COMMENT '总金额',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `approval_status` int DEFAULT NULL,
  `process_instance_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approval_time` datetime DEFAULT NULL,
  `approval_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `execution_status` int DEFAULT NULL,
  `execution_time` datetime DEFAULT NULL,
  `execution_error` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `simulation` bit(1) DEFAULT NULL,
  `notification_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notification_error` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notification_attempts` int DEFAULT NULL,
  `next_notification_time` datetime DEFAULT NULL,
  `source_module` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_chain_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_no` (`no`) USING BTREE,
  KEY `idx_warehouse_id` (`warehouse_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3306014 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WMS 出库单';
/*!40101 SET character_set_client = @saved_cs_client */;

